const workspaceDelete = <T extends JsonRecord = JsonRecord>(mode: 'demo' | 'live', path: string) => mode === 'demo' ? workspaceDemoRequest<T>('DELETE', path) : apiDelete<T>(path);

function fileDisplaySize(value: unknown): string {
  const bytes = Number(value);
  if (!Number.isFinite(bytes) || bytes < 0) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(bytes < 10 * 1024 ? 1 : 0)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(bytes < 10 * 1024 * 1024 ? 1 : 0)} MB`;
}

function fileRelativeDate(value: unknown): string {
  if (typeof value !== 'string' || !value.trim()) return '';
  const date = new Date(value);
  if (Number.isNaN(date.valueOf())) return value;
  const days = Math.floor((Date.now() - date.valueOf()) / 86_400_000);
  if (days < 0) return 'Updated today';
  if (days === 0) return 'Updated today';
  if (days === 1) return 'Updated yesterday';
  if (days < 7) return `Updated ${days} days ago`;
  if (days < 30) return `Updated ${Math.floor(days / 7)} ${Math.floor(days / 7) === 1 ? 'week' : 'weeks'} ago`;
  return `Updated ${date.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: date.getFullYear() === new Date().getFullYear() ? undefined : 'numeric' })}`;
}

function fileFormatLabel(doc: ApiRow): string {
  const format = String(doc.format ?? doc.mime_type ?? doc.type ?? 'document');
  const extension = String(doc.filename ?? doc.name ?? '').split('.').pop();
  if (extension && extension !== String(doc.filename ?? doc.name ?? '')) return extension.toUpperCase();
  if (/^markdown$/i.test(format)) return 'MD';
  if (/^spreadsheet$/i.test(format)) return 'XLS';
  if (/^presentation$/i.test(format)) return 'SLD';
  if (/^word$/i.test(format)) return 'DOC';
  const mimeShort = format.split('/').pop();
  return (mimeShort || format).replace(/^application\./, '').slice(0, 12).toUpperCase();
}
function fileToneForFormat(format: string): string {
  return /pdf/i.test(format) ? 'red' : /xls|sheet|csv/i.test(format) ? 'green' : /ppt|slide/i.test(format) ? 'orange' : /md|markdown/i.test(format) ? 'violet' : 'blue';
}

function orderDemoCodeTree(entries: JsonRecord[]): JsonRecord[] {
  const byPath = new Map(entries.map(entry => [String(entry.path ?? ""), entry]));
  const directory = (path: string, depth: number, expanded = false) => ({ ...(byPath.get(path) ?? { path, type: "directory" }), _codeqDepth: depth, _codeqExpanded: expanded });
  const files = entries.filter(entry => entry.type !== "directory" && !["package.json", "README.md"].includes(String(entry.path ?? "")));
  const codeFiles = files.map(entry => ({ ...entry, _codeqDepth: 3, _codeqExpanded: false }));
  return [
    directory(".next", 1), directory("public", 1), directory("src", 1, true),
    directory("src/app", 2), directory("src/components", 2, true), ...codeFiles,
    directory("src/hooks", 2), directory("src/styles", 2),
    directory("api", 1),
    ...(byPath.has("package.json") ? [{ ...byPath.get("package.json")!, _codeqDepth: 1, _codeqExpanded: false }] : []),
    ...(byPath.has("README.md") ? [{ ...byPath.get("README.md")!, _codeqDepth: 1, _codeqExpanded: false }] : []),
  ];
}

/** Render the subset of Markdown used by document previews without injecting HTML. */
function renderDocumentPreview(content: string) {
  const lines = content.replace(/\r\n?/g, '\n').split('\n');
  const blocks: Array<{ kind: 'heading' | 'paragraph' | 'list'; text?: string; items?: string[] }> = [];
  for (let index = 0; index < lines.length;) {
    const line = lines[index].trim();
    if (!line) { index++; continue; }
    const heading = line.match(/^(?:#{1,6}\s+|\d+[.)]\s+)(.+)$/);
    if (heading) { blocks.push({ kind: 'heading', text: heading[1] }); index++; continue; }
    if (/^[-*+]\s+/.test(line)) {
      const items: string[] = [];
      while (index < lines.length && /^\s*[-*+]\s+/.test(lines[index])) items.push(lines[index++].trim().replace(/^[-*+]\s+/, ''));
      blocks.push({ kind: 'list', items }); continue;
    }
    const paragraph = [line]; index++;
    while (index < lines.length && lines[index].trim() && !/^(?:#{1,6}\s+|\d+[.)]\s+|\s*[-*+]\s+)/.test(lines[index])) paragraph.push(lines[index++].trim());
    blocks.push({ kind: 'paragraph', text: paragraph.join(' ') });
  }
  return blocks.map((block, index) => block.kind === 'heading'
    ? <h3 key={`h-${index}`}>{block.text}</h3>
    : block.kind === 'list'
      ? <ul key={`l-${index}`}>{block.items?.map((item, itemIndex) => <li key={itemIndex}>{item}</li>)}</ul>
      : <p key={`p-${index}`}>{block.text}</p>);
}

