function CodeQLivePreview({ projectId, processId, setProcessId }: { projectId: string; processId: string; setProcessId: (value: string) => void }) {
  const [command, setCommand] = useState('npm run dev -- --host 127.0.0.1');
  const [confirmed, setConfirmed] = useState(false);
  const [message, setMessage] = useState('');
  const toolsUrl = `/api/codebase/projects/${enc(projectId)}/tools`;
  const startMutation = useMutation({
    mutationFn: () => workspacePost('live', toolsUrl, { tool: 'start_process', arguments: { command: command.trim().split(/\s+/), cwd: '' }, approved: true }),
    onSuccess: data => {
      const result = record(data, 'result');
      const process = record(result, 'process');
      const id = String(process?.id ?? result?.process_id ?? result?.id ?? '');
      if (!id) { setMessage(String(record(result, 'approval_required')?.reason ?? 'The backend did not return a managed process ID. Preview was not started.')); return; }
      setProcessId(id); setMessage('Preview process accepted by the backend. Waiting for its local URL and readiness output.');
      setConfirmed(false);
    },
    onError: error => setMessage(errorText(error)),
  });
  const processQuery = useQuery({
    queryKey: ['codeq', 'preview-process', projectId, processId],
    queryFn: async () => {
      const [statusResponse, logsResponse] = await Promise.all([
        workspacePost('live', toolsUrl, { tool: 'process_status', arguments: { process_id: processId }, approved: false }),
        workspacePost('live', toolsUrl, { tool: 'inspect_logs', arguments: { process_id: processId, limit: 20000 }, approved: false }),
      ]);
      return { status: record(statusResponse, 'result'), logs: record(logsResponse, 'result') };
    },
    enabled: Boolean(processId), retry: false,
    refetchInterval: query => String(query.state.data?.status?.status ?? '') === 'running' ? 1500 : false,
  });
  const stopMutation = useMutation({
    mutationFn: () => workspacePost('live', toolsUrl, { tool: 'stop_process', arguments: { process_id: processId }, approved: true }),
    onSuccess: () => { setMessage('Preview process stopped by the backend.'); setProcessId(''); void processQuery.refetch(); },
    onError: error => setMessage(errorText(error)),
  });
  const output = `${String(processQuery.data?.logs?.stdout ?? '')}${String(processQuery.data?.logs?.stderr ?? '')}`.trim();
  const localUrl = output.match(/https?:\/\/(?:localhost|127\.0\.0\.1|\[::1\]):\d+(?:\/[^\s)]*)?/i)?.[0]?.replace(/[.,;]+$/, '');
  const processStatus = String(processQuery.data?.status?.status ?? '');
  const readinessQuery = useQuery({
    queryKey: ['codeq', 'preview-readiness', projectId, processId, localUrl],
    queryFn: async () => workspacePost('live', toolsUrl, { tool: 'probe_local_url', arguments: { url: localUrl, process_id: processId }, approved: false }),
    enabled: Boolean(processId && localUrl && processStatus === 'running'), retry: false,
    refetchInterval: query => record(query.state.data, 'result')?.reachable === true || query.state.dataUpdateCount >= 8 ? false : 2000,
  });
  const readiness = record(readinessQuery.data, 'result');
  useEffect(() => { if (localUrl) setMessage(''); }, [localUrl]);
  const processError = processQuery.error ? errorText(processQuery.error) : processStatus === 'exited' ? `Preview process exited${processQuery.data?.status?.exit_code != null ? ` with code ${String(processQuery.data.status.exit_code)}` : ''}.` : '';
  useEffect(() => {
    if (!processId || !(processQuery.error instanceof ApiError) || processQuery.error.status !== 404) return;
    saveCodeQPreview(projectId, '');
    setMessage('The saved preview process is no longer available. Start a new preview when ready.');
    setProcessId('');
  }, [projectId, processId, processQuery.error, setProcessId]);
  const startPreview = (event: FormEvent) => {
    event.preventDefault();
    if (!confirmed || !command.trim()) return;
    if (!window.confirm('Run this command in the selected CodeQ project workspace? Project scripts can perform actions permitted to this local application account.')) return;
    setMessage(''); startMutation.mutate();
  };
  return <section className="codeq-live-preview-session" aria-label="Live CodeQ preview session">
    {!processId ? <form onSubmit={startPreview}>
      <p className="caption">Start a local preview process inside the selected CodeQ workspace. Nothing starts until you review and confirm the command.</p>
      <label className="field-label">Preview command<input className="input" aria-label="Preview command" value={command} onChange={event => setCommand(event.target.value)} required maxLength={500}/></label>
      <label className="row caption section-space"><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)}/> I reviewed this command and approve running project code locally.</label>
      <button className="btn primary" type="submit" disabled={!confirmed || !command.trim() || startMutation.isPending}>{startMutation.isPending ? 'Starting preview…' : 'Start preview'}</button>
      {startMutation.error && <p className="caption" role="alert">{errorText(startMutation.error)}</p>}
      {message && <p className="caption" role={startMutation.isError ? 'alert' : 'status'}>{message}</p>}
    </form> : <>
      <div className="row between"><span className={`tag ${processStatus === 'running' ? 'green' : processStatus === 'exited' || processQuery.error ? 'red' : 'orange'}`}>{processQuery.isLoading ? 'Checking process…' : processStatus || 'Status unavailable'}</span><div className="row"><button className="icon-btn" type="button" aria-label="Refresh preview status" disabled={processQuery.isFetching} onClick={() => void processQuery.refetch()}><RefreshCw className="icon sm"/></button><button className="btn sm danger" type="button" disabled={stopMutation.isPending} onClick={() => stopMutation.mutate()}>{stopMutation.isPending ? 'Stopping…' : 'Stop preview'}</button></div></div>
      {processQuery.isLoading && <p className="caption" role="status">Reading process status and output from the backend…</p>}
      {processError && <p className="note-panel" role="alert">{processError}</p>}
      {!processError && processStatus === 'running' && (localUrl ? <div className="row between" role="status"><p className="caption">{readiness?.reachable === true ? 'Preview is ready' : readiness?.error ? 'Local preview is not responding yet' : readinessQuery.error ? 'Local preview readiness could not be checked' : readiness?.http_status ? `Preview responded with HTTP ${String(readiness.http_status)}` : 'Checking local preview readiness…'} · <a href={localUrl} target="_blank" rel="noreferrer">{localUrl}</a></p><button className="icon-btn" type="button" aria-label="Retry preview readiness check" disabled={readinessQuery.isFetching} onClick={() => void readinessQuery.refetch()}><RefreshCw className="icon xs"/></button></div> : <p className="caption" role="status">Process is running; waiting for a loopback URL in its output.</p>)}
      {readinessQuery.error && <p className="caption" role="alert">Readiness check failed: {errorText(readinessQuery.error)}</p>}
      {output && <pre className="terminal-window" aria-label="Preview process output" style={{ maxHeight: 190, overflow: 'auto', whiteSpace: 'pre-wrap' }}>{output.slice(-12000)}</pre>}
      {processQuery.error && <button className="btn sm" type="button" disabled={processQuery.isFetching} onClick={() => void processQuery.refetch()}>Retry status</button>}
      {message && <p className="caption" role={startMutation.isError || stopMutation.isError ? 'alert' : 'status'}>{message}</p>}
    </>}
  </section>;
}
