  const [searchText, setSearchText] = useState(''); const [showSearch, setShowSearch] = useState(false); const [gitView, setGitView] = useState<'status' | 'diff' | 'log'>('status');
  const [streamGeneration, setStreamGeneration] = useState(0);
  const [terminalCommand, setTerminalCommand] = useState(''); const [terminalApproved, setTerminalApproved] = useState(false); const [terminalRunId, setTerminalRunId] = useState(''); const [terminalResult, setTerminalResult] = useState<ApiRow | null>(null);
  const [previewProcessId, setPreviewProcessId] = useState(''); const previewProcessIdRef = useRef('');
  useEffect(() => { previewProcessIdRef.current = previewProcessId; }, [previewProcessId]);
