  const runMutation = useMutation({ mutationFn: (query: string) => workspacePost(dataMode, '/api/research/sessions', { query, project: 'default', max_iterations: 3, max_attempts: 3, allow_external: allowExternalResearch }), onSuccess: async data => { const session = record(data, 'session'); if (session?.id) { resetResearchSessionActivity(); researchStreamTerminal.current = dataMode === 'demo'; setSelectedSessionId(String(session.id)); } setEvents(dataMode === 'demo' && session ? rows(session, 'events') : []); if (dataMode === 'demo' && session) setDemoTraceStartSignal(value => value + 1); await queryClient.invalidateQueries({ queryKey: ['research', 'sessions'] }); }, onError: () => undefined });
